void ActiveBody::setDamageState(BodyDamageType state)
{
	switch (state)
	{
	case BODY_PRISTINE:
		internalChangeHealth(m_maxHealth - m_currentHealth, 0);
		break;
	case BODY_DAMAGED:
		internalChangeHealth(m_damagedRatio * m_maxHealth - m_currentHealth, 0);
		break;
	case BODY_REALLYDAMAGED:
		internalChangeHealth(m_reallyDamagedRatio * m_maxHealth - m_currentHealth, 0);
		break;
	case BODY_RUBBLE:
		internalChangeHealth(0.0f - m_currentHealth, 0);
		break;
	}
	setCorrectDamageState(false);
}

// FUNCTION: BFME2 0x004BDB01 size=36 name=?estimateDamage@ActiveBody@@UBEMAAVDamageInfoInput@@@Z evidence=N:ledger tier=B hypothesis:Z
Real ActiveBody::estimateDamage(DamageInfoInput &damageInfo) const
{
	// retail calls the virtual in slot 17 (the map spells 0x004BE1AE non-virtual: a map request)
	validateArmorAndDamageFX();
	return m_curArmor.adjustDamage(&damageInfo, getObject(), true);
}

